 if n=='RESULTS_MANIFEST.tsv':
  with open(p,'a') as f:f.write('\n'+'\t'.join(['phase188_mainline_reorganization','phase188','report',str(d/'MAINLINE_REORGANIZATION_CN.md'),now,'REVIEWED','10 source artifacts archived with SHA256; no new statistics','mainline restored; independent immune/spatial endpoints; auxiliary mechanisms retained'])+'\n')
 else:p.write_text(note+'\n'+p.read_text(),encoding='utf-8')
